#include "stdafx.h"#include "AO.h"KAO::KAO(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Range high",  "Range low",  "mA at Range high",  "mA at Range low",  "High Limit",  "Low Limit",  "Failsafe type",  "Failsafe value",  "Slew Rate"};BOOL KAO::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}